from jsonb_to_recordset($seed$[{"category":"Message only","objection":"They want you to leave a message or send it by text or email.","example_quotes":["I'm sorry this person is not available","It's only by text send it by text","you can send the emails to me and I can forward onto my manager","please, could you send a WhatsApp message"],"call_ids":["b5441ed6-68b3-44b4-b5dd-a9b2153b269d","d6d937ec-0426-4db9-91d6-dfc9bba8c381","bb40b2dd-9b76-4583-93bf-7faa173e9daf","3cfd55c6-53d2-4e00-8a56-9112b42ebf48","1076d161-370b-4c3b-bd64-c4dacdf97bc2","443b9b80-1c21-4b93-9b7e-74ac2552fa5f","c2485a24-974c-4614-b530-ec1ef84a3bd3","86c5cddf-de2f-4921-8331-c3cda1b9cad8","eb8f8f95-d54a-49f3-8422-86980a556691","3b23aacc-d437-4022-b1fa-2ef42b00b66a","91553cec-2e3a-4ce4-a396-21c1818dbc9d","db22b6dd-f006-431e-9418-82be3c5bfd7f"],"times_heard":14,"best_rebuttal":"Of course, I can text you the report link. Can I send it to this number?","our_rebuttal_seen":null,"handled_well":true,"sort_order":0,"desk":"sa"},{"category":"Already have someone","objection":"They already work with someone or manage it themselves.","example_quotes":["go on the website and have a look what we've got and then give me a ring","I do airbnb myself. I don't want it to to um airbnb. No more ok?","I do airbnb myself. So I probably wouldn't undertake this one with you at this moment","the property is already on airbnb and we will be managing ourselves"],"call_ids":["8d120e0a-6681-486a-8a74-077ca2479d41","88ec74e1-29e8-4472-83ef-42233aeef6e3","09866271-c4fd-412b-9e98-be0b3edb6d25","6497f517-2235-41e9-b8b7-2c46664fd500","e0d890db-828f-4e79-9ddd-d60b965b8df9","86e8e659-e8ed-41c1-8a88-1cf95bf2f189","fc5ee4fe-4b6e-445b-9855-1cbfcb491a7e"],"times_heard":8,"best_rebuttal":"That's fine. Most managers charge somewhere between 15 and 20 percent, ours is 9 percent plus VAT. Would it help to see the report so you can compare?","our_rebuttal_seen":"Fair enough, if you already handle it yourself then no worries. I was just seeing if we could save you time and still let you keep the booking income.","handled_well":true,"sort_order":1,"desk":"sa"},{"category":"Not interested","objection":"They're not interested in short lets or the call.","example_quotes":["the landlord's not interested","we wouldn't be interested in that but thank you","we don't go in on any of that","I really don't think that entity will be interested"],"call_ids":["6cb04242-5e30-42de-9d6f-db86c635ae20","ceb04724-3661-4a76-b6d7-d6919ac61c68","b8b8100e-6e17-4bf5-a3c8-6c63e1ae5fc4","17fd8a73-d1f7-41dc-9789-486fb3ddc158","b781cd39-448b-4ad6-bc81-e1f762f97af5","86e8e659-e8ed-41c1-8a88-1cf95bf2f189","29e482c2-bfdc-4fac-81b4-2a47d4096ce0","5a7f6867-0b1d-477f-b867-a3c4882e7952"],"times_heard":8,"best_rebuttal":"No problem, I'm not asking you to decide anything today. The report is free and just shows what your property could make on Airbnb compared with the rent. Can I send it over?","our_rebuttal_seen":"No problem, I just thought I'd check because we work with owners on Airbnb, not long-term lets. If you ever want a quick comparison, I can send one over.","handled_well":false,"sort_order":2,"desk":"sa"},{"category":"Website or call back","objection":"They want you to check the website or call back later.","example_quotes":["we're only in Doncaster","You can give me a ring next week","I'm just in the middle of a viewing can I give you a message back shortly","I've just got to take this other call"],"call_ids":["96bf0890-c6a6-4807-8c3e-f9bf689f8bfe","d6d937ec-0426-4db9-91d6-dfc9bba8c381","1076d161-370b-4c3b-bd64-c4dacdf97bc2","f6ea68e2-5dae-4cb6-9a05-918f10f2eebe","c2485a24-974c-4614-b530-ec1ef84a3bd3","fd8fc46d-ea79-42e6-99f0-6e8bf65bedb5","5afb82c6-216e-4b83-972e-91ad56701593","cedd5684-f638-44a9-aca6-d77be64631e3"],"times_heard":8,"best_rebuttal":"No problem, I'll keep it brief. I can send the free report over now and you can have a look when you've got a minute, then we can speak later if needed.","our_rebuttal_seen":"No problem, I'll call back next week. Would Thursday afternoon still suit you?","handled_well":true,"sort_order":3,"desk":"sa"},{"category":"Different letting type","objection":"They want a tenant in place, not short-let management.","example_quotes":["I've already got someone ... partnered with so hence ... we don't need anyone to work with us","I don't believe that this is something the landlord would be looking at","all of our accommodation is student left so we can only let them to students","not uh open to airbnbs in Inca Studios"],"call_ids":["0dd6a896-fa7f-4244-b545-060d39d3aaa6","bca47c0d-7064-4a8d-8775-774fff3071d7","90dbd0bc-13e7-4b4b-b768-45e895f77d5a","33f9d4f5-5a0f-43ca-9da9-0800cf1b8148","625bbbaf-59a1-438d-b510-c4913825e7ae","1602207e-b867-49a7-8f5d-105ff14b8769"],"times_heard":7,"best_rebuttal":"That's fair, we only work where short lets are allowed. If it's not suitable, I'll leave it there, and if you ever want to compare it against the rent I can send the free report.","our_rebuttal_seen":"Fair enough, we're not a long-term tenancy option. We just help owners compare the Airbnb income with the advertised rent, free of charge.","handled_well":true,"sort_order":4,"desk":"sa"},{"category":"Busy now","objection":"They're busy and want you to call back or reply later.","example_quotes":["so who have you got in Chelton","all I sold out I have to update the adverts","is the 37 Gross on net?","I've got viewings taking place on Saturday"],"call_ids":["09866271-c4fd-412b-9e98-be0b3edb6d25","80ae7012-30c7-4f51-8b9a-700f3554ab17","3b23aacc-d437-4022-b1fa-2ef42b00b66a","fc5ee4fe-4b6e-445b-9855-1cbfcb491a7e","c091da0d-6e54-4b97-9dd0-66beb0d3ee91"],"times_heard":6,"best_rebuttal":"No problem, I'll keep it brief. I can send the report now and you can look at it when you've got time, then we can pick it up later if you want.","our_rebuttal_seen":"No problem, that makes sense. If you want, I can send the report over and you can look at it after the viewings.","handled_well":true,"sort_order":5,"desk":"sa"},{"category":"Future maybe","objection":"They want to look at it later or in the future.","example_quotes":["I'll consider it for the future","I've taken a of your number and I will speak to him if it's something he's interested in","the property is already on airbnb and we will be managing ourselves","we had a chat yesterday... it's not practical for me"],"call_ids":["09866271-c4fd-412b-9e98-be0b3edb6d25","bca47c0d-7064-4a8d-8775-774fff3071d7","6497f517-2235-41e9-b8b7-2c46664fd500","2e418c4e-e8df-4117-b139-040b7d538ada","c091da0d-6e54-4b97-9dd0-66beb0d3ee91"],"times_heard":5,"best_rebuttal":"Of course, no problem. I can send the free report now, and if things change later you've got the figures to come back to.","our_rebuttal_seen":"Of course, no problem. I'll leave it there for now and if things change, you've got the report to come back to.","handled_well":true,"sort_order":6,"desk":"sa"},{"category":"Check with manager","objection":"They need to check with their manager or landlord first.","example_quotes":["I can talk with my manager and we will update you soon","I think you got to discuss this with my manager","he's on holiday at the moment","I just might not have an answer yet from landlords"],"call_ids":["c8e6076e-6215-493c-b8d1-e8f89a7fa5a4","443b9b80-1c21-4b93-9b7e-74ac2552fa5f","b32cd4fc-9f74-44ea-a778-36ad876e80cf"],"times_heard":4,"best_rebuttal":"Of course, no rush. I can send the free report over so they've got the figures to look at, and you can come back to me once you've spoken to them.","our_rebuttal_seen":"Of course, no rush. I'll send the report over, and if it looks worth a look we can pick it up after you've spoken to them.","handled_well":true,"sort_order":7,"desk":"sa"},{"category":"Location and support","objection":"They ask how you manage it from a distance or where you're based.","example_quotes":["how are you going to manage it in Chelton","where are you based?","are we still expected to be involved?","are you a student?"],"call_ids":["09866271-c4fd-412b-9e98-be0b3edb6d25","4fcabd1e-4723-42ec-ac2a-1b13df08660a","fd8fc46d-ea79-42e6-99f0-6e8bf65bedb5"],"times_heard":4,"best_rebuttal":"We handle the guest messages and cleaners through our ops team, and the guest uses a lockbox or key collection. It's managed remotely, and you keep the booking income.","our_rebuttal_seen":"We handle the guest messages and cleaners through our ops team, and the guest uses a lockbox or key collection. It's managed remotely.","handled_well":false,"sort_order":8,"desk":"sa"},{"category":"Price and fee","objection":"They think the fee is too high or it won't be worth it.","example_quotes":["when you pay that fee. We are eventually at a loss","It's just not worth","that's no different to what we do now","if I were to give it to somebody and pay somebody then it defeats the object"],"call_ids":["6497f517-2235-41e9-b8b7-2c46664fd500","625bbbaf-59a1-438d-b510-c4913825e7ae","4fcabd1e-4723-42ec-ac2a-1b13df08660a","fc5ee4fe-4b6e-445b-9855-1cbfcb491a7e"],"times_heard":4,"best_rebuttal":"I understand. Most managers charge somewhere between 15 and 20 percent, ours is 9 percent plus VAT. Software is free in month one, then 29 a month, and the report shows what you'd keep compared with your rent.","our_rebuttal_seen":"I get that. Our fee's 9 percent plus VAT, and most managers charge 15 to 20 percent, so it's usually lighter than people expect.","handled_well":false,"sort_order":9,"desk":"sa"},{"category":"Wrong person or department","objection":"They say you've got the wrong person or department.","example_quotes":["I'm part of the sales team on here... you've come through to probably the wrong department","we just had you registered as one of your our applicant","I'm not sure if it's our sales that you might have inquired with","you spoke to my colleague last month"],"call_ids":["17fd8a73-d1f7-41dc-9789-486fb3ddc158","e0534393-91df-4895-acb1-2912def14d17","5a7f6867-0b1d-477f-b867-a3c4882e7952"],"times_heard":4,"best_rebuttal":"No worries, I may have got wires crossed. I'm only on the short-let side, and I can send a free report if that helps.","our_rebuttal_seen":"No problem, I'm not calling about buying. We help owners run Airbnb lets in Manchester and Liverpool, and the owner keeps the booking income.","handled_well":true,"sort_order":10,"desk":"sa"},{"category":"Already letting or sold","objection":"The property is already let, sold, or unavailable right now.","example_quotes":["I just left it last week","we had a chat yesterday... it's not practical for me","it's in kind of the application process"],"call_ids":["d6d937ec-0426-4db9-91d6-dfc9bba8c381","2e418c4e-e8df-4117-b139-040b7d538ada","86c5cddf-de2f-4921-8331-c3cda1b9cad8"],"times_heard":3,"best_rebuttal":"No worries, I can leave the report with you for when you're ready. It's just an estimate, so there's no pressure if the place isn't available now.","our_rebuttal_seen":"No worries, I can still send the report over for when you're ready. It's just an estimate, so there's no pressure.","handled_well":true,"sort_order":11,"desk":"sa"},{"category":"Building or licence blocks","objection":"The building, licence, or planning rules don't allow Airbnb.","example_quotes":["we're unable to rent that um studio as an airbnb in the building unfortunately","you can't use it ... as a mixed use ... against the licence conditions","it's in kind of the application process"],"call_ids":["8b9b7c3d-788a-424c-b0bf-64a35a811903","ca9a67ec-5390-4b4a-b4a2-92602b6a3617","86c5cddf-de2f-4921-8331-c3cda1b9cad8"],"times_heard":3,"best_rebuttal":"Fair enough, if the rules won't allow it then I'd leave it there. We only work where it's allowed, so no pressure from me.","our_rebuttal_seen":"Fair enough, if the licence won't allow it then I'd leave it there. Thanks for letting me know.","handled_well":true,"sort_order":12,"desk":"sa"},{"category":"Costs and estimate","objection":"They want net figures or worry about extra costs.","example_quotes":["That is not including the managing cost cleaning bills and also the platform advertising charges.","is the 37 Gross on net?","there's cost to come off that"],"call_ids":["625bbbaf-59a1-438d-b510-c4913825e7ae","3b23aacc-d437-4022-b1fa-2ef42b00b66a"],"times_heard":3,"best_rebuttal":"I understand. Most managers charge somewhere between 15 and 20 percent, ours is 9 percent plus VAT. Software is free in month one, then 29 a month, and the report shows what you'd keep compared with your rent.","our_rebuttal_seen":"That's gross. The report shows the estimate before costs, and it explains the fee and other details. Shall I talk you through it after you've had a look?","handled_well":true,"sort_order":13,"desk":"sa"},{"category":"Long-term only","objection":"They only want a long-term tenancy or placement.","example_quotes":["he just wants a long-term placement or tenancy","the landlord wants a tenant who moves in the property lives in the property","if you've got somebody for long term I'd be interested"],"call_ids":["38966efc-df8b-41de-b62c-0aee0aa3cdd7","6cb04242-5e30-42de-9d6f-db86c635ae20","fc5ee4fe-4b6e-445b-9855-1cbfcb491a7e"],"times_heard":3,"best_rebuttal":"I understand, a steady tenant is simple. The report just shows what the same property could make on Airbnb, so you can compare before you decide. Can I send it over?","our_rebuttal_seen":"Yeah, I get that. We only work with owners who want short lets on Airbnb, so I'll leave it there. Thanks for your time.","handled_well":true,"sort_order":14,"desk":"sa"},{"category":"Third-party or sub-let concern","objection":"They say they don't do third-party letting or sub-letting.","example_quotes":["we don't do third-party letters or sub-letting","do you take it as a lease or a rent-to-rent","What are you offering me a fixed fee for doing this"],"call_ids":["6cb04242-5e30-42de-9d6f-db86c635ae20","4fcabd1e-4723-42ec-ac2a-1b13df08660a","fc5ee4fe-4b6e-445b-9855-1cbfcb491a7e"],"times_heard":3,"best_rebuttal":"No, we don't take it as a lease or rent-to-rent. The owner keeps their own Airbnb account and the booking income, and we just manage the short lets.","our_rebuttal_seen":"That's fine, it isn't sub-letting. The owner keeps their Airbnb account and the booking income, and we just handle the guest messages and cleaners.","handled_well":false,"sort_order":15,"desk":"sa"},{"category":"Wrong area","objection":"The property is not in the area you cover.","example_quotes":["we've been approached many many times","where are you located?","how many [name] do you have in Huddersville right now that you manage."],"call_ids":["6cb04242-5e30-42de-9d6f-db86c635ae20","db22b6dd-f006-431e-9418-82be3c5bfd7f"],"times_heard":3,"best_rebuttal":"We manage remotely, with local cleaners and our operations team. Our properties are in Manchester and Liverpool, so I'd confirm your area with Hugo before promising anything.","our_rebuttal_seen":"Ah right, we only cover Manchester and Liverpool for this service. If you've got anything there later, I can take a look.","handled_well":true,"sort_order":16,"desk":"sa"},{"category":"Income too low","objection":"They think the income won't be enough or occupancy is too low.","example_quotes":["you won't get what what we see as a target","for Coventry the occupancy rate is not going to be as high"],"call_ids":["6497f517-2235-41e9-b8b7-2c46664fd500","625bbbaf-59a1-438d-b510-c4913825e7ae"],"times_heard":2,"best_rebuttal":"That's fair, the report's only an estimate. It shows what the property could make on Airbnb versus the advertised rent, so you can judge whether it's worth a look.","our_rebuttal_seen":"Fair enough. The report's only an estimate, but it shows what the place could make on Airbnb versus the rent you've got now.","handled_well":false,"sort_order":17,"desk":"sa"},{"category":"No guaranteed rent","objection":"They want fixed rent or guaranteed income.","example_quotes":["What are you offering me a fixed fee for doing this","it's just not available"],"call_ids":["fc5ee4fe-4b6e-445b-9855-1cbfcb491a7e","625bbbaf-59a1-438d-b510-c4913825e7ae"],"times_heard":2,"best_rebuttal":"No, we don't pay guaranteed rent or take a lease. You keep the booking income, so you benefit when it does well, but income isn't guaranteed.","our_rebuttal_seen":"We don't do guaranteed rent or a fixed fee, no. It's just 9% plus VAT of booking revenue, so it moves with what the property earns.","handled_well":true,"sort_order":18,"desk":"sa"},{"category":"Need proof","objection":"They want references or proof before they proceed.","example_quotes":["send me three [name] that you've dealt with... and the contact number"],"call_ids":["db22b6dd-f006-431e-9418-82be3c5bfd7f"],"times_heard":1,"best_rebuttal":"I get that, but I haven't got any reference details to give out on the phone. What I can do is send the free report so you can see the numbers first.","our_rebuttal_seen":null,"handled_well":false,"sort_order":19,"desk":"sa"},{"category":"Upfront costs","objection":"They're worried about staging or bedding costs upfront.","example_quotes":["the upfront cost is too high"],"call_ids":["625bbbaf-59a1-438d-b510-c4913825e7ae"],"times_heard":1,"best_rebuttal":"I understand. Most managers charge somewhere between 15 and 20 percent, ours is 9 percent plus VAT. Software is free in month one, then 29 a month, and the report shows what you'd keep compared with your rent.","our_rebuttal_seen":"There's no onboarding fee from us. The only software cost starts from month two, and the first month's free.","handled_well":false,"sort_order":20,"desk":"sa"},{"category":"Happy as is","objection":"We are happy as we are.","best_rebuttal":"That's fair, and nothing has to change. The free report just shows what the same property could earn on Airbnb, so you know your options. Shall I send it over?","example_quotes":[],"call_ids":[],"times_heard":0,"our_rebuttal_seen":null,"handled_well":null,"sort_order":21,"desk":"sa"},{"category":"Self-managing","objection":"I do it myself.","best_rebuttal":"That makes sense. We can take the guest messages, pricing and cleaning coordination off your hands, and you still keep your Airbnb account and the booking income.","example_quotes":[],"call_ids":[],"times_heard":0,"our_rebuttal_seen":null,"handled_well":null,"sort_order":22,"desk":"sa"},{"category":"Timing","objection":"I need to think about it.","best_rebuttal":"Of course. It's easier to think it over with the numbers in front of you, and there's no obligation. Shall I send you the report?","example_quotes":[],"call_ids":[],"times_heard":0,"our_rebuttal_seen":null,"handled_well":null,"sort_order":23,"desk":"sa"}]$seed$::jsonb)
  as x(category text, objection text, example_quotes jsonb, call_ids uuid[], times_heard int, best_rebuttal text, our_rebuttal_seen text, handled_well boolean, sort_order int, desk text);
